import { useEffect, useState, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { Wifi, Download, Upload, Activity, MapPin, Server } from 'lucide-react';
import { ResponsiveContainer, AreaChart, Area, XAxis, Tooltip } from 'recharts';

function SpeedChecker() {
  const [download, setDownload] = useState(0);
  const [upload, setUpload] = useState(0);
  const [ping, setPing] = useState(0);
  const [testing, setTesting] = useState(false);
  const [history, setHistory] = useState([]);

  // FIX: safe production API base
  const API_BASE = process.env.REACT_APP_API_URL || window.location.origin;

  const runTest = useCallback(async () => {
    try {
      setTesting(true);
      setDownload(0);
      setUpload(0);
      setPing(0);
      setHistory([]);

      // =========================
      // PING TEST
      // =========================
      const pingStart = performance.now();

      const pingResp = await fetch(`${API_BASE}/api/ping`, {
        cache: 'no-store',
      });

      if (!pingResp.ok) throw new Error(`Ping failed: ${pingResp.status}`);

      await pingResp.json();

      const ping = Math.round(performance.now() - pingStart);
      setPing(ping);

      // =========================
      // DOWNLOAD TEST
      // =========================
      const isLocal = API_BASE.includes('localhost') || API_BASE.includes('127.0.0.1');

      const duration = isLocal ? 8000 : 12000;
      const chunkSize = isLocal ? 2 * 1024 * 1024 : 5 * 1024 * 1024;

      const start = performance.now();

      let bytes = 0;
      let lastBytes = 0;
      let lastTime = performance.now();

      while (performance.now() - start < duration) {
        try {
          const res = await fetch(`${API_BASE}/api/download?size=${chunkSize}`, {
            cache: 'no-store',
          });

          if (!res.ok) throw new Error('Download failed');

          const reader = res.body?.getReader();
          if (!reader) throw new Error('Stream not supported');

          while (true) {
            const now = performance.now();

            if (now - start >= duration) break;

            const { value, done } = await reader.read();
            if (done) break;

            if (value) bytes += value.byteLength;

            if (now - lastTime >= 1000) {
              const mbps = ((bytes - lastBytes) * 8) / ((now - lastTime) / 1000) / 1_000_000;

              const speed = Math.max(0, Math.round(mbps));

              setDownload(speed);

              setHistory((prev) => {
                const updated = [...prev, { time: prev.length, speed }].slice(-25);

                return updated;
              });

              lastBytes = bytes;
              lastTime = now;
            }
          }
        } catch (e) {
          console.error('Download chunk error:', e);
          break;
        }
      }

      const totalTime = (performance.now() - start) / 1000;
      const finalDownload = (bytes * 8) / totalTime / 1_000_000;

      setDownload(Math.round(finalDownload));

      // =========================
      // UPLOAD TEST (FIXED)
      // =========================
      const uploadChunk = new Uint8Array(256 * 1024);
      const uploadStart = performance.now();

      let lastUpload = 0;

      for (let i = 0; i < 10; i++) {
        try {
          const res = await fetch(`${API_BASE}/api/upload`, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/octet-stream',
            },
            body: uploadChunk,
          });

          if (!res.ok) throw new Error(`Upload failed: ${res.status}`);

          const data = await res.json();

          // SAFE fallback (important fix)
          const speed =
            data?.speed ||
            (data?.receivedBytes
              ? (data.receivedBytes * 8) / ((performance.now() - uploadStart) / 1000) / 1_000_000
              : 0);

          if (speed > 0) {
            lastUpload = speed;
            setUpload(Math.round(speed));
          }
        } catch (err) {
          console.error('Upload error:', err);
          break;
        }
      }

      setUpload(Math.round(lastUpload));

      setTesting(false);
    } catch (err) {
      console.error(err);
      setTesting(false);
      alert(`Speed test failed: ${err.message}`);
    }
  }, [API_BASE]);

  useEffect(() => {}, []);

  return (
    <div className="main-bg">
      <div className="container py-4">
        {/* HEADER */}
        <div className="topbar">
          <img src="/logo.png" alt="logo" style={{ height: 50 }} />

          <button className="run-btn" onClick={runTest} disabled={testing}>
            {testing ? 'TESTING...' : 'RUN TEST'}
          </button>
        </div>

        {/* CARDS */}
        <div className="row g-4 mt-2">
          <MiniCard title="Download" value={`${download} Mbps`} icon={<Download />} />
          <MiniCard title="Upload" value={`${upload} Mbps`} icon={<Upload />} />
          <MiniCard title="Ping" value={`${ping} ms`} icon={<Activity />} />
          <MiniCard title="Status" value={testing ? 'Testing' : 'Stable'} icon={<Wifi />} />
        </div>

        {/* MAIN */}
        <div className="glass-panel mt-4">
          <motion.div
            key={download}
            initial={{ scale: 0.8, opacity: 0 }}
            animate={{ scale: 1, opacity: 1 }}
            className="speed-display"
          >
            <h1 className="speed-value">{download}</h1>
            <div className="speed-unit">Mbps</div>
          </motion.div>

          <ResponsiveContainer width="100%" height={300}>
            <AreaChart data={history}>
              <XAxis dataKey="time" stroke="#6ecfff" />
              <Tooltip />
              <Area dataKey="speed" stroke="#00f7ff" fill="#00f7ff" />
            </AreaChart>
          </ResponsiveContainer>
        </div>

        {/* INFO */}
        <div className="row g-4 mt-2">
          <InfoCard title="Server" value="Local" icon={<Server />} />
          <InfoCard title="Location" value="Your PC" icon={<MapPin />} />
          <InfoCard title="Connection" value="Stable" icon={<Wifi />} />
        </div>

        {/* FOOTER */}
        <footer className="footer-section">
          <Link to="/privacy-policy">Privacy</Link> | <Link to="/terms-of-service">Terms</Link> |{' '}
          <Link to="/about-us">About</Link>
        </footer>
      </div>
    </div>
  );
}

// ================= COMPONENTS =================

function MiniCard({ title, value, icon }) {
  return (
    <div className="mini-card">
      <div className="mini-icon">{icon}</div>
      <div className="mini-title">{title}</div>
      <div className="mini-value">{value}</div>
    </div>
  );
}

function InfoCard({ title, value, icon }) {
  return (
    <div className="info-card">
      <div className="info-icon">{icon}</div>
      <div className="info-title">{title}</div>
      <div className="info-value">{value}</div>
    </div>
  );
}

export default SpeedChecker;
